                continue
            out[r][c] = 0
            nr = min(r + 1, barrier - 1)
            out[nr][c] = 4
            if nr == barrier - 1:
                for d in (-1, 1):
                    rr, cc = nr - 1, c + d
                    while rr >= 0 and 0 <= cc < w:
                        if out[rr][cc] == 0:
                            out[rr][cc] = 4
                        rr -= 1
                        cc += d
    return out
