    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    divider = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), h)
    points = [(r, c) for r in range(divider) for c, value in enumerate(grid[r]) if value == 4]
    # Above the divider, every point shifts down one row.
    for r, c in points:
        out[r][c] = 0
    for r, c in points:
        out[r + 1][c] = 4
    # Point rows also induce the two up-and-out diagonals, but only when
    # the marker is not already on the top boundary.
    for r, c in points:
        if r > 0:
            for dc in (-1, 1):
                rr, cc = r - 1, c + dc
                while rr >= 0 and 0 <= cc < w:
                    if out[rr][cc] == 0:
                        out[rr][cc] = 4
                    rr -= 1
                    cc += dc
    return out
