    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bar = next((r for r, row in enumerate(grid) if all(v == 2 for v in row)), None)
    if bar is None:
        return out
    markers = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 4]

    # Markers move one cell toward the 2-row. The divider blocks markers
    # on its far side, so those remain unchanged.
    for r, c in markers:
        if r < bar:
            out[r][c] = 0
            landing = r + 1
            out[landing][c] = 4
            # A marker landing directly beside the divider sends two
            # diagonal rays away from it, toward the outer edge.
            if landing == bar - 1:
                for dc in (-1, 1):
                    rr, cc = landing - 1, c + dc
                    while rr >= 0 and 0 <= cc < w:
                        if out[rr][cc] == 0:
                            out[rr][cc] = 4
                        rr -= 1
                        cc += dc
        elif r > bar:
            landing = r - 1
            if landing != bar:
                out[r][c] = 0
                out[landing][c] = 4
                if landing == bar + 1:
                    for dc in (-1, 1):
                        rr, cc = landing + 1, c + dc
                        while rr < h and 0 <= cc < w:
                            if out[rr][cc] == 0:
                                out[rr][cc] = 4
                            rr += 1
                            cc += dc
    return out
